import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ProcessWalkthroughProps = Record<string, any>;

const ProcessWalkthrough: React.FC<ProcessWalkthroughProps> = ({
  backgroundColor = "#050507",
  transparentBackground = false,
  durationInSeconds = 15,
  title = "Growth Protocol",
  subtitle = "AI-Powered Workflow",
  highlightColor = "#0A84FF", // Apple-style vibrant blue
  textColor = "#FFFFFF",
  secondaryTextColor = "#8E8E93",
  steps = [
    "Content Ideation",
    "Script Generation",
    "Filming Protocol",
    "Automated Editing",
    "Multi-Platform Posting",
    "Analytics Review"
  ],
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations optimized for 9:16 (1080x1920)
  const safeZoneTop = height * 0.15;
  const safeZoneBottom = height * 0.1;
  const contentHeight = height - safeZoneTop - safeZoneBottom;
  
  // Divide vertical space
  const headerHeight = contentHeight * 0.2;
  const listHeight = contentHeight * 0.8;
  const itemHeight = listHeight / Math.max(steps.length, 1);

  // Timing logic
  const totalFrames = durationInSeconds * fps;
  const introFrames = fps * 1.5;
  const outroFrames = fps * 1.5;
  const processFrames = totalFrames - introFrames - outroFrames;
  const timePerStep = processFrames / Math.max(steps.length, 1);

  // Header Animation
  const headerEntrance = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1.2 },
  });
  
  const headerOpacity = interpolate(headerEntrance, [0, 1], [0, 1]);
  const headerY = interpolate(headerEntrance, [0, 1], [60, 0]);

  // Overall Progress Line Animation
  const totalProgress = Math.max(0, Math.min(1, (frame - introFrames) / processFrames));
  const smoothTotalProgress = spring({
    frame: frame - introFrames,
    fps,
    config: { damping: 20, mass: 1 },
    durationInFrames: processFrames, // Smooth over the entire process
  });

  const progressLineHeight = interpolate(
    totalProgress,
    [0, 1],
    [0, listHeight - itemHeight],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      
      {/* Background ambient glow based on highlight color */}
      <div style={{
        position: "absolute",
        top: "20%",
        left: "50%",
        width: width * 0.8,
        height: height * 0.5,
        background: `radial-gradient(circle, ${highlightColor}15 0%, transparent 70%)`,
        transform: "translate(-50%, -50%)",
        filter: "blur(100px)",
        transition: "none",
      }} />

      <div style={{
        display: "flex",
        flexDirection: "column",
        width: "100%",
        height: "100%",
        paddingTop: safeZoneTop,
        paddingBottom: safeZoneBottom,
        paddingLeft: width * 0.1,
        paddingRight: width * 0.1,
        boxSizing: "border-box",
        transition: "none",
      }}>
        
        {/* Header Section */}
        <div style={{
          height: headerHeight,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          opacity: headerOpacity,
          transform: `translateY(${headerY}px)`,
          transition: "none",
        }}>
          <h2 style={{
            fontSize: 42,
            fontWeight: 600,
            color: highlightColor,
            margin: 0,
            marginBottom: 16,
            letterSpacing: 2,
            textTransform: "uppercase",
            transition: "none",
          }}>
            {subtitle}
          </h2>
          <h1 style={{
            fontSize: 84,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            lineHeight: 1.1,
            letterSpacing: -1.5,
            transition: "none",
          }}>
            {title}
          </h1>
        </div>

        {/* List Section Container */}
        <div style={{
          height: listHeight,
          position: "relative",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}>
          
          {/* Background track line */}
          <div style={{
            position: "absolute",
            left: 48,
            top: itemHeight / 2,
            width: 4,
            height: listHeight - itemHeight,
            backgroundColor: `${secondaryTextColor}30`,
            borderRadius: 2,
            transition: "none",
          }} />

          {/* Animated active progress line */}
          <div style={{
            position: "absolute",
            left: 48,
            top: itemHeight / 2,
            width: 4,
            height: progressLineHeight,
            backgroundColor: highlightColor,
            borderRadius: 2,
            boxShadow: `0 0 15px ${highlightColor}`,
            transition: "none",
          }} />

          {steps.map((stepText, index) => {
            // Timing for this specific step
            const itemStart = introFrames + (index * timePerStep);
            const itemEnd = itemStart + timePerStep;

            // Entrance animation (initial staggered appearance)
            const enterSpring = spring({
              frame: Math.max(0, frame - (index * 8)), // Stagger initial load
              fps,
              config: { damping: 14, mass: 1 }
            });

            // Activation animation (when it becomes the current step)
            const activateSpring = spring({
              frame: Math.max(0, frame - itemStart),
              fps,
              config: { damping: 12, mass: 0.8 }
            });

            // Deactivation animation (when it moves to completed)
            const deactivateSpring = spring({
              frame: Math.max(0, frame - itemEnd),
              fps,
              config: { damping: 12, mass: 0.8 }
            });

            // Calculate derived styles
            // Scale: starts at 0.9, pops to 1.05 when active, settles at 1.0 when done
            const itemScale = 0.9 + (activateSpring * 0.15) - (deactivateSpring * 0.05);
            
            // Opacity: starts at 0 -> 0.4 (waiting), goes to 1.0 (active), drops to 0.7 (done)
            const baseOpacity = interpolate(enterSpring, [0, 1], [0, 0.4]);
            const activeOpacityBoost = activateSpring * 0.6;
            const deactivateOpacityDrop = deactivateSpring * 0.3;
            const itemOpacity = baseOpacity + activeOpacityBoost - deactivateOpacityDrop;

            // X-Offset: slides in slightly
            const itemX = interpolate(enterSpring, [0, 1], [40, 0]) + 
                          interpolate(activateSpring, [0, 1], [0, 15]) - 
                          interpolate(deactivateSpring, [0, 1], [0, 15]);

            // Circle logic
            const isCompleted = frame >= itemEnd;
            const isActive = frame >= itemStart && frame < itemEnd;
            
            // Circle inner scale (fills up)
            const circleFillScale = activateSpring;
            
            // Text color transition
            const currentTextColor = isActive 
              ? textColor 
              : isCompleted 
                ? `${textColor}99` // 60% opacity white
                : secondaryTextColor;

            // Card background for active state (sophisticated frosted glass feel)
            const bgOpacity = interpolate(activateSpring, [0, 1], [0, 0.05]) - 
                              interpolate(deactivateSpring, [0, 1], [0, 0.05]);
            const borderOpacity = interpolate(activateSpring, [0, 1], [0, 0.15]) - 
                                  interpolate(deactivateSpring, [0, 1], [0, 0.15]);

            return (
              <div 
                key={index}
                style={{
                  height: itemHeight,
                  display: "flex",
                  alignItems: "center",
                  position: "relative",
                  opacity: itemOpacity,
                  transform: `translateX(${itemX}px) scale(${itemScale})`,
                  transformOrigin: "left center",
                  transition: "none",
                }}
              >
                {/* Active Highlight Card Background */}
                <div style={{
                  position: "absolute",
                  left: 80,
                  right: 0,
                  top: "10%",
                  bottom: "10%",
                  backgroundColor: `rgba(255, 255, 255, ${bgOpacity})`,
                  border: `1px solid rgba(255, 255, 255, ${borderOpacity})`,
                  borderRadius: 24,
                  boxShadow: isActive ? `0 20px 40px rgba(0,0,0,0.2), 0 0 20px ${highlightColor}20` : 'none',
                  zIndex: 0,
                  transition: "none",
                }} />

                {/* Step Node / Circle */}
                <div style={{
                  width: 100,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  zIndex: 2,
                  transition: "none",
                }}>
                  <div style={{
                    width: 48,
                    height: 48,
                    borderRadius: 24,
                    backgroundColor: backgroundColor,
                    border: `4px solid ${isActive || isCompleted ? highlightColor : `${secondaryTextColor}40`}`,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    position: "relative",
                    transition: "none",
                    boxShadow: isActive ? `0 0 20px ${highlightColor}60` : 'none',
                  }}>
                    {/* Inner fill when active/complete */}
                    <div style={{
                      width: 24,
                      height: 24,
                      borderRadius: 12,
                      backgroundColor: highlightColor,
                      transform: `scale(${circleFillScale})`,
                      opacity: isCompleted ? 0.5 : 1,
                      transition: "none",
                    }} />
                  </div>
                </div>

                {/* Step Text */}
                <div style={{
                  flex: 1,
                  paddingLeft: 30,
                  zIndex: 2,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  transition: "none",
                }}>
                  <span style={{
                    fontSize: 24,
                    fontWeight: 600,
                    color: highlightColor,
                    marginBottom: 8,
                    opacity: activateSpring, // Only show step number when active/past
                    letterSpacing: 2,
                    textTransform: "uppercase",
                    transition: "none",
                  }}>
                    Step 0{index + 1}
                  </span>
                  <span style={{
                    fontSize: 48,
                    fontWeight: isActive ? 600 : 500,
                    color: currentTextColor,
                    letterSpacing: -0.5,
                    transition: "none",
                  }}>
                    {stepText}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ProcessWalkthrough;